import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new __InvMutHandleStub())); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // keep the domain wide: only bound ancillary data to a reasonable size
        vm.assume(ancillaryData.length < 128);

        // the optimistic asserter is the address c was constructed with (the stub)
        address asserter = address(c.optimisticAsserter());

        // 1) authorized call: succeeds and (in the correct contract) emits PriceRequestAdded
        uint256 g1 = gasleft();
        vm.prank(asserter);
        c.requestPrice(identifier, time, ancillaryData);
        uint256 okGas = g1 - gasleft();

        // 2) unauthorized call: reverts with "Not the optimistic asserter"
        bool ok;
        uint256 g2 = gasleft();
        try c.requestPrice(identifier, time, ancillaryData) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 failGas = g2 - gasleft();

        // General rule: a successful (authorized) requestPrice must consume strictly more gas
        // than a rejected one, because emitting PriceRequestAdded is extra work the correct
        // contract always performs. The mutant's emptied body makes the successful call the
        // cheapest path, violating the inequality.
        assertTrue(ok == false && okGas > failGas);
    }
}

